int main() {
    while (scanf("%d", &n) == 1 && n != 0) {
        // Read distance matrix
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                scanf("%d", &dist[i][j]);
            }
        }

        // Subtract 2 from each distance to get switch distances
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                dist[i][j] -= 2;
            }
        }

        // Initialize degrees to 0
        memset(degree, 0, sizeof(degree));

        // Find edges: For each pair (i,j), if dist[i][j] == 1, they are directly connected
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (dist[i][j] == 1) {
                    degree[i]++;
                    degree[j]++;
                }
            }
        }

        // Collect internal node degrees (degree > 1)
        int internal_degrees[MAXN];
        int internal_count = 0;
        for (int i = 0; i < n; i++) {
            if (degree[i] > 1) {
                internal_degrees[internal_count++] = degree[i];
            }
        }

        // Sort ascending
        for (int i = 0; i < internal_count - 1; i++) {
            for (int j = i + 1; j < internal_count; j++) {
                if (internal_degrees[i] > internal_degrees[j]) {
                    int tmp = internal_degrees[i];
                    internal_degrees[i] = internal_degrees[j];
                    internal_degrees[j] = tmp;
