#define MAXN 505

static int D[MAXN][MAXN];
static int parent_[MAXN];
static int is_internal[MAXN];
static int degree_[2 * MAXN];
static int leaves_of_internal[2 * MAXN];
static int repr_leaf[2 * MAXN];

static int cmp_int(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x > y) - (x < y);
}

int main(void) {
    int n;
    while (scanf("%d", &n) == 1) {
        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= n; ++j) {
                scanf("%d", &D[i][j]);
            }
        }

        if (n == 1) {
            printf("0\n\n");
            continue;
        }

        for (int i = 1; i <= n; ++i) {
            parent_[i] = 0;
            is_internal[i] = 0;
        }

        int total_nodes = n;

        /* Reconstruct rooted hierarchy using laminar families:
           For each leaf i, choose parent as the smallest cluster S(i,j)
           among all j, where S(i,j) = {k | D[i][k] < D[i][j]}.
           Two leaves have same parent iff these sets are equal. */
        for (int i = 1; i <= n; ++i) {
            int best_j = -1;
            int best_sz = n + 1;

            for (int j = 1; j <= n; ++j) {
                if (i == j) continue;
                int sz = 0;
                for (int k = 1; k <= n; ++k) {
                    if (D[i][k] < D[i][j]) sz++;
                }
                if (sz > 0 && sz < best_sz) {
                    best_sz = sz;
                    best_j = j;
                }
            }

            if (best_j == -1) continue;

            int found = 0;
            for (int x = n + 1; x <= total_nodes; ++x) {
                int rep = repr_leaf[x];
                if (D[i][best_j] != D[rep][best_j]) continue;

                int same = 1;
                for (int k = 1; k <= n; ++k) {
                    int a = (D[i][k] < D[i][best_j]);
                    int b = (D[rep][k] < D[rep][best_j]);
                    if (a != b) {
                        same = 0;
                        break;
                    }
                }
                if (same) {
                    parent_[i] = x;
                    leaves_of_internal[x]++;
                    found = 1;
                    break;
                }
            }

            if (!found) {
                ++total_nodes;
                is_internal[total_nodes] = 1;
                repr_leaf[total_nodes] = i;
                leaves_of_internal[total_nodes] = 1;
                parent_[i] = total_nodes;
            }
        }

        /* Build inclusion tree among internal nodes:
           parent of cluster A is the smallest cluster strictly containing A. */
        for (int x = n + 1; x <= total_nodes; ++x) {
            int repx = repr_leaf[x];
            int size_x = 0;
            for (int k = 1; k <= n; ++k) {
                if (parent_[k] == x) size_x++;
            }

            int best = 0, best_sz = n + 1;

            for (int y = n + 1; y <= total_nodes; ++y) {
                if (x == y) continue;
                int repy = repr_leaf[y];

                int contains = 1;
                int size_y = 0;
                for (int k = 1; k <= n; ++k) {
                    int inx = (parent_[k] == x);
                    int iny = (parent_[k] == y);
                    if (inx && !iny) {
                        contains = 0;
                        break;
                    }
                    if (iny) size_y++;
                }

                if (contains && size_y > size_x && size_y < best_sz) {
                    best_sz = size_y;
                    best = y;
                }

                (void)repy;
            }
            parent_[x] = best;
        }

        for (int i = 1; i <= total_nodes; ++i) degree_[i] = 0;

        for (int v = 1; v <= total_nodes; ++v) {
            if (parent_[v] != 0) {
                degree_[v]++;
                degree_[parent_[v]]++;
            }
        }

        int cnt_internal = total_nodes - n;
        int *ans = (int *)malloc(sizeof(int) * (cnt_internal > 0 ? cnt_internal : 1));
        int p = 0;
        for (int i = n + 1; i <= total_nodes; ++i) {
            ans[p++] = degree_[i];
        }

        qsort(ans, p, sizeof(int), cmp_int);

        printf("%d\n", p);
        for (int i = 0; i < p; ++i) {
            if (i) printf(" ");
            printf("%d", ans[i]);
        }
        printf("\n");

        free(ans);
    }

    return 0;
}

