/*
 * Reconstruct tree from leaf distance matrix and output degrees of internal nodes.
 *
 * Model:
 * - Given pairwise distances between leaves (computers).
 * - The full network is a tree whose leaves are exactly the computers.
 * - Internal nodes are switches.
 * - Need degrees of internal nodes in ascending order.
 *
 * Key fact:
 * For an additive tree metric on leaves, the minimal rooted-cluster family can be
 * recovered from all sets S(a,b) = { x | d(a,x)+d(x,b)=d(a,b) } over leaf pairs.
 * Each such set is exactly the leaf set of the path between a and b intersected
 * with leaves; in a tree with leaves only at terminals, these generate all edge-induced
 * clusters. Building the laminar family of distinct such subsets gives the internal nodes.
 *
 * Simpler constructive approach used here:
 * Reconstruct the unique weighted tree using the classical additive phylogeny algorithm,
 * then compute degrees of internal nodes.
 *
 * Constraints are not provided in the prompt, so implementation is written carefully
 * but assumes the matrix is valid and n is moderate enough for O(n^3).
 */
public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Edge {
        int to;
        long w;
        Edge(int to, long w) {
            this.to = to;
            this.w = w;
        }
    }

    static ArrayList<Edge>[] g;
    static int nextNode;

    static void ensureCapacity(int n) {
        if (g.length >= n) return;
        int old = g.length;
        g = Arrays.copyOf(g, n);
        for (int i = old; i < n; i++) g[i] = new ArrayList<>();
    }

    static void addEdge(int u, int v, long w) {
        g[u].add(new Edge(v, w));
        g[v].add(new Edge(u, w));
    }

    static void removeEdge(int u, int v) {
        for (int i = 0; i < g[u].size(); i++) {
            if (g[u].get(i).to == v) {
                g[u].remove(i);
                break;
            }
        }
        for (int i = 0; i < g[v].size(); i++) {
            if (g[v].get(i).to == u) {
                g[v].remove(i);
                break;
            }
        }
    }

    static class PathResult {
        ArrayList<Integer> nodes = new ArrayList<>();
        ArrayList<Long> weights = new ArrayList<>();
    }

    static boolean dfsPath(int u, int p, int target, PathResult res) {
        if (u == target) {
            res.nodes.add(u);
            return true;
        }
        for (Edge e : g[u]) {
            if (e.to == p) continue;
            if (dfsPath(e.to, u, target, res)) {
                res.nodes.add(u);
                res.weights.add(e.w);
                return true;
            }
        }
        return false;
    }

    static int insertLeafOnPath(int i, int k, long x, long limbLen) {
        PathResult pr = new PathResult();
        dfsPath(i, -1, k, pr);
        Collections.reverse(pr.nodes);
        Collections.reverse(pr.weights);

        long dist = 0;
        for (int idx = 0; idx < pr.weights.size(); idx++) {
            long w = pr.weights.get(idx);
            int u = pr.nodes.get(idx);
            int v = pr.nodes.get(idx + 1);
            if (dist + w == x) {
                int attach = v;
                addEdge(attach, currentLeaf, limbLen);
                return attach;
            } else if (dist + w > x) {
                long left = x - dist;
                long right = w - left;
                int newNode = nextNode++;
                ensureCapacity(nextNode + 5);

                removeEdge(u, v);
                addEdge(u, newNode, left);
                addEdge(newNode, v, right);
                addEdge(newNode, currentLeaf, limbLen);
                return newNode;
            }
            dist += w;
        }
        // x == 0 case should attach at i
        addEdge(i, currentLeaf, limbLen);
        return i;
    }

    static int currentLeaf;

    static void build(long[][] D, int m, int[] labels) {
        if (m == 2) {
            addEdge(labels[0], labels[1], D[0][1]);
            return;
        }

        int j = m - 1;
        long limb = Long.MAX_VALUE;
        for (int a = 0; a < m - 1; a++) {
            for (int b = 0; b < m - 1; b++) {
                if (a == b) continue;
                long val = (D[a][j] + D[j][b] - D[a][b]) / 2;
                if (val < limb) limb = val;
            }
        }

        int iFound = -1, kFound = -1;
        long x = -1;
        outer:
        for (int i = 0; i < m - 1; i++) {
            for (int k = 0; k < m - 1; k++) {
                if (i == k) continue;
                if (D[i][k] == D[i][j] + D[j][k] - 2 * limb) {
                    iFound = i;
                    kFound = k;
                    x = D[i][j] - limb;
                    break outer;
                }
            }
        }

        long[][] D2 = new long[m - 1][m - 1];
        for (int a = 0; a < m - 1; a++) {
            System.arraycopy(D[a], 0, D2[a], 0, m - 1);
        }
        int[] labels2 = new int[m - 1];
        System.arraycopy(labels, 0, labels2, 0, m - 1);

        build(D2, m - 1, labels2);

        currentLeaf = labels[j];
        insertLeafOnPath(labels[iFound], labels[kFound], x, limb);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        int t;
        try {
            t = fs.nextInt();
        } catch (Exception e) {
            return;
        }

        while (t-- > 0) {
            int n = fs.nextInt();
            long[][] D = new long[n][n];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    D[i][j] = fs.nextLong();
                }
            }

            g = new ArrayList[Math.max(2 * n + 5, 10)];
            for (int i = 0; i < g.length; i++) g[i] = new ArrayList<>();
            nextNode = n;

            int[] labels = new int[n];
            for (int i = 0; i < n; i++) labels[i] = i;

            if (n == 1) {
                // No internal nodes.
                out.append(0).append('\n');
                if (t > 0) out.append('\n');
                continue;
            }

            build(D, n, labels);

            ArrayList<Integer> degs = new ArrayList<>();
            for (int v = n; v < nextNode; v++) {
                degs.add(g[v].size());
            }
            Collections.sort(degs);

            out.append(degs.size()).append('\n');
            for (int i = 0; i < degs.size(); i++) {
                if (i > 0) out.append(' ');
                out.append(degs.get(i));
            }
            out.append('\n');
            if (t > 0) out.append('\n');
        }

        System.out.print(out.toString());
    }
}

