    // Distance from clusters to others
    vector<vector<long long>> curDist = dist;
    int nextNode = n;

    while (active.size() > 1) {
        int m = active.size();
        // Find closest pair
        int a = 0, b = 1;
        long long best = LLONG_MAX;
        for (int i = 0; i < m; i++) {
            for (int j = i + 1; j < m; j++) {
                if (curDist[active[i]][active[j]] < best) {
                    best = curDist[active[i]][active[j]];
                    a = i;
                    b = j;
                }
            }
        }

        int u = active[a];
        int v = active[b];

        // Create new internal node
        int newNode = nextNode++;
        parent[u] = newNode;
        parent[v] = newNode;
        children[newNode].push_back(u);
        children[newNode].push_back(v);

        // Compute distances from newNode to all other active nodes
        vector<long long> newDist(m, 0);
        for (int i = 0; i < m; i++) {
            if (i == a || i == b) continue;
            int w = active[i];
            newDist[i] = (curDist[u][w] + curDist[v][w] - curDist[u][v]) / 2;
        }

        // Build new active list
        vector<int> newActive;
        vector<vector<long long>> nextDist(m - 1, vector<long long>(m - 1, 0));

        // Add newNode
        int idx = 0;
        newActive.push_back(newNode);
        for (int i = 0; i < m; i++) {
            if (i == a || i == b) continue;
            newActive.push_back(active[i]);
            // distance from newNode to this node
            nextDist[0][idx + 1] = newDist[i];
            nextDist[idx + 1][0] = newDist[i];
            idx++;
        }

        // distances among remaining original nodes
        int p = 1;
        for (int i = 0; i < m; i++) {
            if (i == a || i == b) continue;
            int q = 1;
            for (int j = 0; j < m; j++) {
                if (j == a || j == b) continue;
                nextDist[p][q] = curDist[active[i]][active[j]];
                q++;
            }
            p++;
        }

        active = move(newActive);
        curDist = move(nextDist);
    }

    // Count degrees of internal nodes
    vector<int> degrees(nextNode, 0);
    for (int i = 0; i < nextNode; i++) {
        if (parent[i] != -1) {
            degrees[parent[i]]++;
        }
    }

    vector<int> internalDegrees;
    for (int i = n; i < nextNode; i++) {
        internalDegrees.push_back(degrees[i]);
    }

    sort(internalDegrees.begin(), internalDegrees.end());
    for (int d : internalDegrees) {
        cout << d << "\n";
    }

    return 0;
}

