    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    if (!(cin >> T)) return 0;

    cout.setf(std::ios::fmtflags(0), std::ios::basefield);

    while (T--) {
        int n;
        cin >> n;

        vector<vector<long double>> full(2 * n + 5, vector<long double>(2 * n + 5, 0));
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                long double x;
                cin >> x;
                full[i][j] = x;
            }
        }

        int maxNodes = 2 * n + 5;
        vector<vector<int>> adj(maxNodes);
        vector<int> active;
        active.reserve(2 * n);
        for (int i = 0; i < n; ++i) active.push_back(i);

        int nextNode = n;

        while ((int)active.size() > 2) {
            int m = active.size();
            vector<long double> r(maxNodes, 0);

            for (int ii = 0; ii < m; ++ii) {
                int i = active[ii];
                long double sum = 0;
                for (int jj = 0; jj < m; ++jj) {
                    int j = active[jj];
                    sum += full[i][j];
                }
                r[i] = sum;
            }

            int bi = -1, bj = -1;
            long double bestQ = 0;
            bool first = true;

            for (int ii = 0; ii < m; ++ii) {
                for (int jj = ii + 1; jj < m; ++jj) {
                    int i = active[ii], j = active[jj];
                    long double q = (m - 2) * full[i][j] - r[i] - r[j];
                    if (first || q < bestQ) {
                        first = false;
                        bestQ = q;
                        bi = ii;
                        bj = jj;
                    }
                }
            }

            int x = active[bi], y = active[bj];
            int u = nextNode++;

            adj[u].push_back(x);
            adj[u].push_back(y);
            adj[x].push_back(u);
            adj[y].push_back(u);

            for (int kk = 0; kk < m; ++kk) {
                int k = active[kk];
                if (k == x || k == y) continue;
                full[u][k] = full[k][u] = (full[x][k] + full[y][k] - full[x][y]) / 2.0L;
            }
            full[u][u] = 0;

            vector<int> newActive;
            newActive.reserve(m - 1);
            for (int v : active) {
                if (v != x && v != y) newActive.push_back(v);
            }
            newActive.push_back(u);
            active.swap(newActive);
        }

        if ((int)active.size() == 2) {
            int a = active[0], b = active[1];
            adj[a].push_back(b);
            adj[b].push_back(a);
        }

        vector<int> ans;
        for (int v = n; v < nextNode; ++v) {
            ans.push_back((int)adj[v].size());
        }
        sort(ans.begin(), ans.end());

        for (int i = 0; i < (int)ans.size(); ++i) {
            if (i) cout << ' ';
            cout << ans[i];
        }
        cout << '\n';
    }

    return 0;
}

import sys


def solve_case(n, D):
    # Build one valid weighted tree from the additive matrix using recursive split.
    # Leaves are 0..n-1, internal nodes created as needed.
    adj = {}
    next_id = n

    def add_edge(u, v, w):
        adj.setdefault(u, []).append((v, w))
        adj.setdefault(v, []).append((u, w))

    def build(labels):
        nonlocal next_id
        if len(labels) == 1:
            return labels[0]
        if len(labels) == 2:
            u, v = labels
            add_edge(u, v, D[u][v])
            return None  # no single root needed by parent in this base case

        a = labels[0]
        b = labels[1]
        # Compute x_i = dist(a, i) + dist(a, b) - dist(b, i) = 2 * dist(lca_path_point, a?) up to constant
        # For additive tree, grouping by x identifies components attached along path a-b.
        groups = {}
        dab = D[a][b]
        for x in labels:
            key = D[a][x] - D[b][x]
            groups.setdefault(key, []).append(x)

        keys = sorted(groups.keys())

        # If all in one group, choose different pair to avoid degeneracy
        if len(keys) == 1:
            for i in range(len(labels)):
                for j in range(i + 1, len(labels)):
                    a2, b2 = labels[i], labels[j]
                    groups2 = {}
                    for x in labels:
                        key = D[a2][x] - D[b2][x]
                        groups2.setdefault(key, []).append(x)
                    if len(groups2) > 1:
                        a, b = a2, b2
                        groups = groups2
                        keys = sorted(groups.keys())
                        dab = D[a][b]
                        break
                else:
                    continue
                break

        # Create path nodes for each consecutive attachment point
        path_nodes = []
        path_pos = []
        for key in keys:
            # position from a along path a-b
            pos2 = dab + key  # equals 2 * dist(a, attach)
            path_pos.append(pos2 // 2)
            path_nodes.append(next_id)
            adj.setdefault(next_id, [])
            next_id += 1

        # connect path chain
        for i in range(len(path_nodes) - 1):
            w = path_pos[i + 1] - path_pos[i]
            add_edge(path_nodes[i], path_nodes[i + 1], w)

        # attach a and b if needed
        if path_pos[0] > 0:
            add_edge(a, path_nodes[0], path_pos[0])
        else:
            # merge a into first path node logically by replacing occurrences later
            add_edge(a, path_nodes[0], 0)
        if path_pos[-1] < dab:
            add_edge(b, path_nodes[-1], dab - path_pos[-1])
        else:
            add_edge(b, path_nodes[-1], 0)

        # recurse on each group excluding the path representative if singleton endpoint group
        for idx, key in enumerate(keys):
            grp = groups[key]
            hub = path_nodes[idx]
            sub = [x for x in grp if x != a and x != b]
            if not sub:
                continue
            if len(sub) == 1:
                add_edge(hub, sub[0], D[a][sub[0]] - path_pos[idx])
            else:
                # Build subtree on grp itself if it doesn't already include path endpoint semantics.
                # We need a recursive construction for the vertices in grp.
                # To keep distances correct, build subtree for sub only, then connect one chosen leaf by computed length.
                root = build(sub)
                if root is not None:
                    # connect root to hub by inferring distance using any leaf in sub:
                    leaf = sub[0]
                    # distance from hub to leaf:
                    dhl = D[a][leaf] - path_pos[idx]
                    add_edge(hub, root, dhl)
        return path_nodes[0]

    # The above generic builder is complicated; for this problem we only need degrees of internal nodes.
    # A much simpler and robust way: reconstruct topology via Buneman splits using all triples.
    # We'll instead use a recursive partition method that works for additive matrices of leaf-labeled trees.

    adj = {}
    next_id = n

    def add(u, v):
        adj.setdefault(u, []).append(v)
        adj.setdefault(v, []).append(u)

    def rec(S):
        nonlocal next_id
        if len(S) == 1:
            return S[0]
        if len(S) == 2:
            x, y = S
            nid = next_id
            next_id += 1
            add(nid, x)
            add(nid, y)
            return nid

        a = S[0]
        b = S[1]
        vals = {}
        for x in S:
            vals[x] = D[a][x] - D[b][x]

        groups = {}
        for x in S:
            groups.setdefault(vals[x], []).append(x)

        if len(groups) == 1:
            # star-like / unresolved by this pair, try another pair
            found = False
            for i in range(len(S)):
                for j in range(i + 1, len(S)):
                    a = S[i]
                    b = S[j]
                    vals = {x: D[a][x] - D[b][x] for x in S}
                    groups = {}
                    for x in S:
                        groups.setdefault(vals[x], []).append(x)
                    if len(groups) > 1:
                        found = True
                        break
                if found:
                    break

        if len(groups) == 1:
            # all leaves attached to one center
            nid = next_id
            next_id += 1
            for x in S:
                add(nid, x)
            return nid

        nid = next_id
        next_id += 1
        for g in groups.values():
            child = rec(g)
            add(nid, child)
        return nid

    root = rec(list(range(n)))

    degs = []
    for v in adj:
        if v >= n:
            d = len(adj[v])
            if d > 1:
                degs.append(d)
    degs.sort()
    return degs


def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    ptr = 0
    out = []

    # Support either:
    #  t followed by cases
    # or a single case starting with n.
    def parse_one(ptr):
        if ptr >= len(data):
            return None, ptr
        n = int(data[ptr])
        ptr += 1
        D = []
        for _ in range(n):
            row = list(map(int, data[ptr:ptr + n]))
            ptr += n
            D.append(row)
        return (n, D), ptr

    # Try first token as number of cases if possible
    t = int(data[ptr])
    ptr += 1
    cases = []
    ok = True
    save_ptr = ptr
    for _ in range(t):
        case, ptr = parse_one(ptr)
        if case is None:
            ok = False
            break
        cases.append(case)
    if ptr != len(data):
        ok = False

    if not ok:
        ptr = 0
        cases = []
        case, ptr = parse_one(ptr)
        if case is not None:
            cases.append(case)

    for idx, (n, D) in enumerate(cases):
        ans = solve_case(n, D)
        out.append(" ".join(map(str, ans)) if ans else "")
    sys.stdout.write("\n".join(out))


if __name__ == "__main__":
    main()
